local function rarity_conflicts_with_catalog(meta,rarity,legacy_mythic)
    if meta and meta.quality=='set' and rarity~=7 and rarity<8 then return true end
    if not meta or (meta.quality~='unique' and meta.quality~='mythic') then return false end
    if rarity~=6 and rarity<8 then return true end
    return meta.quality=='mythic' and rarity<8 and not legacy_mythic
end
