local function named_item(name)
    return type(name)=='string' and name~='' and name:lower()~='ph'
        and not name:lower():find('[ph',1,true) and not name:lower():find('placeholder',1,true)
end
local function build_picker_catalog()
    -- Keep legacy source IDs available for saved widgets even when their rows
    -- belong in another picker, or are not equipment at all.
    legacy_unique_items=item_unique
    local groups={unique={},mythic={},charm={},set={},seal={}}
    local function add(row,kind,quality)
        local id=row.sno_id
        local meta=current_items[id] or {}
        kind=meta.kind or kind
        quality=meta.quality or quality
        if kind=='equipment' and not (catalog_slots[meta.slot] or equipment_types[row.item_type] or utils.mythics[id]) then return end
        if kind=='equipment' and utils.mythics[id] then quality='mythic' end
        local group=kind=='equipment' and (quality=='unique' or quality=='mythic') and quality
            or kind=='charm' and (quality=='unique' or quality=='mythic') and 'charm'
            or kind=='charm' and quality=='set' and 'set'
            or kind=='seal' and (quality=='unique' or quality=='mythic') and 'seal'
        if not group then return end
        local name=named_item(meta.name) and meta.name or row.name
        if not named_item(name) then return end
        local previous=groups[group][id]
        local classes=meta.classes or row.class or previous and previous.class
        if type(classes)~='table' or #classes==0 then classes={'all'} end
        local item_type=kind=='charm' and 'Charm' or kind=='seal' and 'Seal'
            or meta.slot or row.item_type or 'Equipment'
        groups[group][id]={sno_id=id,name=name,description=name,item_type=item_type,class=classes,
            set=row.set or previous and previous.set or '',quality=quality}
    end
    for _,row in ipairs(legacy_unique_items) do
        add(row,equipment_types[row.item_type] and 'equipment' or 'other','unique')
    end
    for id,name in pairs(utils.mythics) do add({sno_id=id,name=name,class={'all'}},'equipment','mythic') end
    for _,row in ipairs(item_unique_charm) do add(row,'charm','unique') end
    for _,row in ipairs(item_set_charm) do add(row,'charm','set') end
    for id,name in pairs(utils.mythic_seals) do add({sno_id=id,name=name,class={'all'}},'seal','mythic') end
    for id,meta in pairs(current_items) do
        -- Internal assets without a real localized name do not become new picks.
        if named_item(meta.name) and (meta.quality=='unique' or meta.quality=='mythic' or meta.quality=='set') then
            add({sno_id=id,name=meta.name,class=meta.classes},meta.kind,meta.quality)
        end
    end
    local function list(group)
        local result={}
        for _,row in pairs(groups[group]) do result[#result+1]=row end
        table.sort(result,function(a,b)
            if a.name==b.name then return a.sno_id<b.sno_id end
            return a.name<b.name
        end)
        return result
    end
    item_unique,item_mythic=list('unique'),list('mythic')
    item_unique_charm,item_set_charm,item_special_seal=list('charm'),list('set'),list('seal')
end
