local legacy_asset_types = {
    helm='helm',hlm='helm',chest='chest',trs='chest',gloves='gloves',glove='gloves',glv='gloves',
    pants='pants',leg='pants',boots='boots',bts='boots',amulet='amulet',necklace='amulet',ring='ring',
    focus='offhand',book='offhand',totem='offhand',shield='offhand',
    offhandssorc='offhand',offhandsnecro='offhand',offhandswarlock='offhand',offhandsdruid='offhand',
    quarterstaff='weapon_2h',glaive='weapon_2h',polearm='weapon_2h',bow='weapon_2h',crossbow='weapon_2h',staff='weapon_2h',
    ['2hsword']='weapon_2h',['2hmace']='weapon_2h',['2haxe']='weapon_2h',['2hscythe']='weapon_2h',
    ['2hpolearm']='weapon_2h',['2hstaff']='weapon_2h',
    sword='weapon_1h',mace='weapon_1h',axe='weapon_1h',scythe='weapon_1h',wand='weapon_1h',flail='weapon_1h',dagger='weapon_1h',
    ['1hsword']='weapon_1h',['1hmace']='weapon_1h',['1haxe']='weapon_1h',['1hscythe']='weapon_1h',
    ['1hwand']='weapon_1h',['1hflail']='weapon_1h',['1hdagger']='weapon_1h',
}
function utils.get_item_type(item)
    local ok,id=pcall(function() return item:get_sno_id() end)
    if not ok or type(id)~='number' or id<=0 or id>=math.huge or id~=math.floor(id) then return 'unknown' end
    local meta=current_items[id]
    if meta then
        if meta.kind=='equipment' then return catalog_slots[meta.slot] or 'unknown' end
        if meta.kind=='charm' then return 'talisman_charm' end
        if meta.kind=='seal' then return 'talisman_seal' end
        if meta.kind=='cache' then return 'cache' end
        -- A known fish/quest/recipe is never gear merely because of a name fragment.
        return 'unknown'
    end
    local readable,name=pcall(function() return item:get_name() end)
    if not readable or type(name)~='string' then return 'unknown' end
    name=string.lower(name)
    if name:match('cache') then return 'cache' end
    if name:match('tempering') then return 'tempering' end
    -- A gear word anywhere in an unknown asset name is not a category witness.
    -- Accept only explicit legacy asset prefixes; catalogued non-gear never
    -- reaches this compatibility fallback.
    if name:find('qst',1,true) or name:find('quest',1,true) or name:find('cosmetic',1,true)
        or name:find('recipe',1,true) then return 'unknown' end
    if name:match('^talisman_seal[_%d]') then return 'talisman_seal' end
    if name:match('^talisman_charm[_%d]') then return 'talisman_charm' end
    local token=name:match('^([%w]+)_') or name:match('^([%w]+)$')
    token=token and token:gsub('%d+$','') or ''
    return legacy_asset_types[token] or 'unknown'
end
function utils.is_salvage_or_sell(item,action)
    local is_salvage_or_sell, _, _ = utils.is_salvage_or_sell_with_data(item, action)
    return is_salvage_or_sell
end
local classify_equipment
function utils.is_salvage_or_sell_with_data(item,action)
    local ok, is_salvage_or_sell, affix_count, is_max_aspect = pcall(classify_equipment, item, action)
    if not ok then return false, 0, false end
    return is_salvage_or_sell == true, affix_count or 0, is_max_aspect == true
end
classify_equipment = function(item,action)
    if not utils.can_modify_item(item) then return false,0,false end

    local item_id = item:get_sno_id()

    local item_type = utils.get_item_type(item)
    if item_type == 'cache' then return false, 0, false end
    if item_type == 'unknown' then return false, 0, false end
    if item_type == 'tempering' then return false, 0, false end

    local rarity = item:get_rarity()
    if not valid_rarity(rarity) then return false,0,false end
    local is_unique  = rarity == 6
    local is_mythic  = rarity>=8 or utils.mythics[item_id] ~= nil
    local ga_count,ga_readable = utils.get_item_ga_count(item)

    -- QQT_Warpigz_v2 local patch (H3): "Always keep mythics" (default on; the
    -- old WarPigz Alfred's mythic_always_keep key) overrides every rule, the
    -- loot filter included. Switched off, mythics still never take the
    -- loot-filter or junk action: only the GA, name-list and mythic rules.
    if is_mythic and utils.settings.mythic_always_keep ~= false then return false, 0, false end

    -- loot filter mode: in-game filter is the sole rule
    if utils.settings.loot_filter_mode and not is_mythic then
        local ok, filtered = pcall(function() return item:is_filtered_by_loot_filter() end)
        if ok and filtered==true then return action == utils.item_enum['SALVAGE'], 0, false end
        return false, 0, false
    end

    -- loot filter equipment mode: in-game filter decides equipment, Rosie handles the rest
    if utils.settings.loot_filter_equipment and not is_mythic then
        local ok, filtered = pcall(function() return item:is_filtered_by_loot_filter() end)
        if ok and filtered==true then return action==utils.item_enum['SALVAGE'],0,false end
        return false,0,false
    end

    if not ga_readable then return false,0,false end

    local meta=current_items[item_id]
    if rarity_conflicts_with_catalog(meta,rarity,is_mythic) then
        return false,0,false -- metadata never substitutes a destructive rarity decision
    end

    local ancestry_ok,is_ancestral=pcall(function() return item:is_ancestral() end)
    local junk_ok,is_junk=pcall(function() return item:is_junk() end)
    if not ancestry_ok or type(is_ancestral)~='boolean' or not junk_ok or type(is_junk)~='boolean' then return false,0,false end

    -- non-ancestral path
    if not is_ancestral and not is_mythic then
        if is_junk then
            return utils.settings.item_junk == action, 0, false
        elseif is_unique then
            return utils.settings.item_unique == action, 0, false
        else
            return utils.settings.item_legendary_or_lower == action, 0, false
        end
    end

    -- ancestral path
    if is_junk and not is_mythic then
        return utils.settings.ancestral_item_junk == action, 0, false
    end

    -- mythic
    if is_mythic then
        if utils.settings.ancestral_mythic_ga_count > 0 and ga_count >= utils.settings.ancestral_mythic_ga_count then
            return false, 0, false  -- GA override: keep
        end
        if utils.settings.ancestral_unique_filter and utils.is_correct_mythic(item) then
            return false, 0, false  -- name filter: keep
        end
        return utils.settings.ancestral_item_mythic == action, 0, false
    end

    -- unique
    if is_unique then
        if utils.settings.ancestral_unique_ga_count > 0 and ga_count >= utils.settings.ancestral_unique_ga_count then
            return false, 0, false  -- GA override: keep
        end
        if utils.settings.ancestral_unique_filter and utils.is_correct_unique(item) then
            return false, 0, false  -- name filter: keep
        end
        return utils.settings.ancestral_item_unique == action, 0, false
    end

    -- non-unique, non-mythic (rare/magic/legendary)
    if utils.settings.ancestral_ga_count > 0 and ga_count >= utils.settings.ancestral_ga_count then
        if utils.settings.ancestral_filter and utils.settings.ancestral_affix then
            local matched = 0
            for _, affix in pairs(item:get_affixes()) do
                if utils.is_correct_affix(item_type, affix) then matched = matched + 1 end
            end
            if matched >= utils.settings.ancestral_affix_count then
                return false, matched, false
            end
        else
            return false, 0, false
        end
    end
    return utils.settings.ancestral_item_legendary == action, 0, false
end
function utils.is_mounted()
    local local_player = get_local_player()
    return local_player~=nil and local_player:get_attribute(attributes.CURRENT_MOUNT) < 0
end
local update_debounce_time = get_time_since_inject()
local update_debounce_timeout = 0.5
-- QQT_Warpigz_v2 (M3): a forced recount (every service pulse, every menu
-- frame) runs at most every FORCED_INTERVAL; force == 'now' (a request) is
-- immediate.
local FORCED_INTERVAL = 0.25
-- QQT_Warpigz_v2 (M2): one unreadable item is skipped (kept), it never ends
-- the census or the trip.
local function census_entry(item)
    if utils.settings.skip_favorite and item:is_locked() then return nil end
    local is_salvage, affix_count, is_max_aspect = utils.is_salvage_or_sell_with_data(item,utils.item_enum['SALVAGE'])
    local is_sell = utils.is_salvage_or_sell(item,utils.item_enum['SELL'])
    local is_stash = not is_salvage and not is_sell
    if is_stash then
        local item_type = utils.get_item_type(item)
        if (item_type == 'cache' and utils.settings.skip_cache) then
            is_stash = false
        end
    end
    return {
        is_salvage = is_salvage,
        is_sell = is_sell,
        is_stash = is_stash,
        affix_count = affix_count,
        is_max_aspect = is_max_aspect,
        item = item
    }
end
local function talisman_census(item)
    if utils.settings.skip_favorite and item:is_locked() then return nil end
    if utils.should_sell_talisman(item) then return 'sell' end
    if utils.should_salvage_talisman(item) then return 'salvage' end
    return 'stash'
end
local census_errors = {}
local function census_error(why)
    local message = tostring(why)
    if census_errors[message] then return end
    census_errors[message] = true
    console.print('[Rosie] Item skipped this census (unreadable): ' .. message)
end
function utils.update_tracker_count(local_player,force)
    if not local_player then return end
    local now = get_time_since_inject()
    if not force and update_debounce_time + update_debounce_timeout > now then return end
    if force == true and now >= update_debounce_time and now - update_debounce_time < FORCED_INTERVAL then return end
    update_debounce_time = now


    local items = local_player:get_inventory_items()
    local cached_inventory = {}
    local salvage_counter = 0
    local sell_counter = 0
    local stash_counter = 0
    for _, item in pairs(items) do
        if item then
            local ok, entry = pcall(census_entry, item)
            if not ok then
                census_error(entry)
            elseif entry then
                if entry.is_salvage then
                    salvage_counter = salvage_counter + 1
                elseif entry.is_sell then
                    sell_counter = sell_counter + 1
                elseif entry.is_stash then
                    stash_counter = stash_counter + 1
                end
                cached_inventory[#cached_inventory+1] = entry
            end
        else
            utils.log('no item??')
        end
    end
    local salvage_talisman_counter = 0
    local stash_talisman_counter = 0
    local sell_equipment_counter = sell_counter
    local sell_talisman_counter = 0
    local talisman_items = local_player:get_talisman_items()
    for _, item in pairs(talisman_items) do
        local ok, kind = pcall(talisman_census, item)
        if not ok then
            census_error(kind)
        elseif kind == 'sell' then
            sell_counter = sell_counter + 1
            sell_talisman_counter = sell_talisman_counter + 1
        elseif kind == 'salvage' then
            salvage_talisman_counter = salvage_talisman_counter + 1
        elseif kind == 'stash' then
            stash_talisman_counter = stash_talisman_counter + 1
        end
    end
    tracker.cached_inventory = cached_inventory
    tracker.inventory_count = local_player:get_item_count()
    tracker.talisman_inventory_count = #talisman_items
    tracker.salvage_count = salvage_counter
    tracker.salvage_talisman_count = salvage_talisman_counter
    tracker.stash_talisman_count = stash_talisman_counter
    tracker.sell_count = sell_counter
    tracker.sell_equipment_count = sell_equipment_counter
    tracker.sell_talisman_count = sell_talisman_counter
    tracker.stash_count = stash_counter
    tracker.inventory_full = tracker.inventory_count >= utils.settings.max_inventory

    local need_repair = false
    local items = local_player:get_equipped_items()
    for _, item in pairs(items) do
        local ok, durability = pcall(function() return item:get_durability() end)
        if not ok then census_error(durability)
        elseif type(durability) == 'number' and durability <= 10 then
            need_repair = true
        end
    end
    tracker.need_repair = need_repair
    tracker.need_stash_socketables = utils.settings.stash_socketables == utils.stash_extra_enum['FULL'] and #local_player:get_socketable_items() >= utils.settings.max_inventory
    tracker.need_stash_consumables = utils.settings.stash_consumables == utils.stash_extra_enum['FULL'] and #local_player:get_consumable_items() >= utils.settings.max_inventory
    tracker.need_stash_keys        = utils.settings.stash_keys        == utils.stash_extra_enum['FULL'] and #local_player:get_dungeon_key_items() >= utils.settings.max_inventory
    tracker.talisman_inventory_full    = #talisman_items >= utils.settings.max_inventory

    tracker.need_trigger = tracker.inventory_full or
        tracker.need_repair or
        tracker.need_stash_socketables or
        tracker.need_stash_consumables or
        tracker.need_stash_keys or
        tracker.talisman_inventory_full

    tracker.name = utils.settings.plugin_label
    tracker.version = utils.settings.plugin_version
end
-- QQT_Warpigz_v2 (L1): the unused import/export helpers were removed; they
-- redirected the process-wide io.output and had no caller.
function utils.dump_tracker_info(tracker_data)
    local keys={}
    for key,data in pairs(tracker_data) do
        if type(key)=='string' and (type(data)=='string' or type(data)=='number' or type(data)=='boolean') then
            keys[#keys+1]=key
        end
    end
    table.sort(keys)
    console.print('[Rosie] Current service diagnostics:')
    for _,key in ipairs(keys) do console.print('[Rosie] '..key..': '..tostring(tracker_data[key])) end
end

